import React from 'react';
import '../../../styles/GlobalStyles.css';

const OrganizerDashboard = () => {
  // Dummy data for demonstration
  const events = [
    { id: 1, title: 'Tech Conference 2025', date: '2025-05-01', registrations: 150, ticketSales: 3000 },
    { id: 2, title: 'Startup Pitch Session', date: '2025-06-15', registrations: 80, ticketSales: 1200 },
  ];

  return (
    <div className="container">
      <div className="card">
        <h2>Organizer Dashboard</h2>
        <p>Manage your events, view ticket sales, and track performance.</p>
        
        {/* Event Management Section */}
        <section>
          <h3>Event Management</h3>
          <button className="btn" style={{ marginRight: '1rem' }}>Create New Event</button>
          <button className="btn">Manage Events</button>
          <div style={{ marginTop: '1rem' }}>
            <h4>Your Events</h4>
            <ul>
              {events.map(event => (
                <li key={event.id} style={{ marginBottom: '0.5rem' }}>
                  <strong>{event.title}</strong> | Date: {event.date} | Registrations: {event.registrations} | Ticket Sales: ₹{event.ticketSales}
                </li>
              ))}
            </ul>
          </div>
        </section>
        
        {/* Analytics & Insights Section */}
        <section style={{ marginTop: '2rem' }}>
          <h3>Analytics & Insights</h3>
          <p>Total Events: {events.length}</p>
          <p>Total Registrations: {events.reduce((acc, event) => acc + event.registrations, 0)}</p>
          <p>Total Revenue: ₹{events.reduce((acc, event) => acc + event.ticketSales, 0)}</p>
        </section>
        
        {/* Notifications & Updates Section */}
        <section style={{ marginTop: '2rem' }}>
          <h3>Notifications & Updates</h3>
          <button className="btn">Send Update to Attendees</button>
        </section>
      </div>
    </div>
  );
};

export default OrganizerDashboard;
